package com.dossier.api.domain.ent.mkt;

import jakarta.persistence.*;
import java.io.Serializable;
import java.time.Instant;

/**
 * Ties an assigned opportunity ({@code mkt_opportunity}) to the consultant's OWN application (person-owned, no FK). At most one LIVE link per
 * opportunity: {@code live_key} is generated by the database ({@code opportunity_id} while {@code unlinked_at} is null) and unique per org.
 * Table {@code pipeline_application_link}. Every query goes through an org-scoped repository method.
 */
@Entity
@Table(name = "pipeline_application_link")
public class MktPipelineApplicationLink implements Serializable {

    private static final long serialVersionUID = 1L;

    public static final String SOURCE_SUBMIT_DETECT = "SUBMIT_DETECT";
    public static final String SOURCE_CONSULTANT = "CONSULTANT";
    public static final String SOURCE_LINKER = "LINKER";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private Long id;

    @Column(name = "org_id", nullable = false)
    private Long orgId;

    @Column(name = "opportunity_id", nullable = false)
    private Long opportunityId;

    @Column(name = "consultant_id", nullable = false)
    private Long consultantId;

    @Column(name = "personal_application_id", nullable = false)
    private Long personalApplicationId;

    @Column(name = "talent_application_id")
    private Long talentApplicationId;

    @Column(name = "source", length = 16, nullable = false)
    private String source;

    @Column(name = "linked_at", nullable = false)
    private Instant linkedAt = Instant.now();

    @Column(name = "unlinked_at")
    private Instant unlinkedAt;

    /** Generated by the database; never written. */
    @Column(name = "live_key", insertable = false, updatable = false)
    private Long liveKey;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Long getOrgId() { return orgId; }
    public void setOrgId(Long orgId) { this.orgId = orgId; }
    public Long getOpportunityId() { return opportunityId; }
    public void setOpportunityId(Long opportunityId) { this.opportunityId = opportunityId; }
    public Long getConsultantId() { return consultantId; }
    public void setConsultantId(Long consultantId) { this.consultantId = consultantId; }
    public Long getPersonalApplicationId() { return personalApplicationId; }
    public void setPersonalApplicationId(Long personalApplicationId) { this.personalApplicationId = personalApplicationId; }
    public Long getTalentApplicationId() { return talentApplicationId; }
    public void setTalentApplicationId(Long talentApplicationId) { this.talentApplicationId = talentApplicationId; }
    public String getSource() { return source; }
    public void setSource(String source) { this.source = source; }
    public Instant getLinkedAt() { return linkedAt; }
    public void setLinkedAt(Instant linkedAt) { this.linkedAt = linkedAt; }
    public Instant getUnlinkedAt() { return unlinkedAt; }
    public void setUnlinkedAt(Instant unlinkedAt) { this.unlinkedAt = unlinkedAt; }
    public Long getLiveKey() { return liveKey; }
}
